#!/usr/bin/env python3
"""Generate the independent native Windows localization header."""
import argparse
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent

def generated_files():
    messages = json.loads((ROOT / 'platform/windows/messages.json').read_text(encoding='utf-8'))
    files = {}
    def cpp_string(value):
        escaped = value.replace('\\', '\\\\').replace('"', '\\"')
        escaped = escaped.replace('\r', '\\r').replace('\n', '\\n').replace('\t', '\\t')
        return 'L"' + escaped + '"'

    windows_catalog = (
        '// Generated by scripts/sync-native-localizations.py. Edit platform/windows/messages.json.\n'
        '#pragma once\n#include <string>\n#include <string_view>\n#include <unordered_map>\n\n'
        'inline std::wstring L(std::wstring_view source) {\n'
        '    static const bool english = PRIMARYLANGID(GetUserDefaultUILanguage()) == LANG_ENGLISH;\n'
        '    if (!english) return std::wstring(source);\n'
        '    static const std::unordered_map<std::wstring_view, std::wstring_view> catalog = {\n'
    )
    for key, value in messages.items():
        windows_catalog += f'        {{{cpp_string(key)}, {cpp_string(value)}}},\n'
    windows_catalog += (
        '    };\n    const auto found = catalog.find(source);\n'
        '    return std::wstring(found == catalog.end() ? source : found->second);\n}\n'
        'struct NativeTranslation { std::wstring_view english; std::wstring_view chinese; };\n'
        'inline const wchar_t* L(const char* source) {\n'
        '    static const std::unordered_map<std::string_view, NativeTranslation> catalog = {\n'
    )
    for key, value in messages.items():
        windows_catalog += f'        {{{json.dumps(key, ensure_ascii=False)}, {{{cpp_string(value)}, {cpp_string(key)}}}}},\n'
    windows_catalog += (
        '    };\n    const auto found = catalog.find(source);\n'
        '    if (found == catalog.end()) return L"";\n'
        '    return (PRIMARYLANGID(GetUserDefaultUILanguage()) == LANG_ENGLISH ? found->second.english : found->second.chinese).data();\n}\n'
    )
    files[ROOT / 'platform/windows/Localization.h'] = windows_catalog
    return files

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    stale = []
    for path, contents in generated_files().items():
        if args.check:
            if not path.exists() or path.read_text(encoding='utf-8') != contents:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(contents, encoding='utf-8')
    if stale:
        parser.exit(1, 'Stale localization resources: ' + ', '.join(stale) + '\n')


if __name__ == '__main__':
    main()
